-- Run as a superuser on a lab server you own (PostgreSQL 16)
-- 1. Stop the PUBLIC pseudo-role from connecting or creating objects
REVOKE ALL ON DATABASE shopdb FROM PUBLIC;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;

-- 2. A group role that holds permissions; people and apps inherit it
CREATE ROLE reporting_ro NOLOGIN;
GRANT CONNECT ON DATABASE shopdb TO reporting_ro;
GRANT USAGE ON SCHEMA public TO reporting_ro;
GRANT SELECT ON orders, products TO reporting_ro;   -- no customers table

-- 3. A login role for the reporting job (secret is a placeholder)
CREATE ROLE report_job LOGIN PASSWORD '<generated-secret>' CONNECTION LIMIT 5;
GRANT reporting_ro TO report_job;

-- 4. Hide rows from a role that must see only its own region
ALTER TABLE orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY eu_only ON orders FOR SELECT TO reporting_ro
    USING (region = 'EU');

